#include "containers.h"
#ifndef CD_MUTANT
#define CD_MUTANT 0
#endif
static int array_valid(const struct cd_array*a){return a&&a->live&&a->length<=a->capacity&&(!a->capacity||a->data);}
enum cd_status cd_array_init(struct cd_array*a,int*p,size_t cap){if(!a||(!p&&cap)||cap>SIZE_MAX/sizeof*p)return CD_INVALID;*a=(struct cd_array){p,0,cap,1};return CD_OK;}
enum cd_status cd_array_insert(struct cd_array*a,size_t at,const int*value){if(!array_valid(a)||!value||at>a->length)return CD_INVALID;if(a->length==a->capacity)return CD_FULL;int staged=*value;for(size_t i=a->length;i>at;--i)a->data[i]=a->data[i-1];a->data[at]=CD_MUTANT==1?*value:staged;++a->length;return CD_OK;}
enum cd_status cd_array_erase(struct cd_array*a,size_t at,int*out){if(!array_valid(a)||!out||at>=a->length)return CD_INVALID;int old=a->data[at];for(size_t i=at+1;i<a->length;++i)a->data[i-1]=a->data[i];--a->length;*out=old;return CD_OK;}
enum cd_status cd_array_get(const struct cd_array*a,size_t at,int*out){if(!array_valid(a)||!out||at>=a->length)return CD_INVALID;*out=a->data[at];return CD_OK;}
enum cd_status cd_array_destroy(struct cd_array*a){if(!array_valid(a))return CD_INVALID;a->data=0;a->length=a->capacity=0;a->live=0;return CD_OK;}
static size_t magnitude(ptrdiff_t stride){return stride<0?(size_t)(-(stride+1))+1:(size_t)stride;}
static int view_valid(const struct cd_view*v){if(!v||(!v->base&&v->extent)||!v->stride||v->extent>SIZE_MAX/sizeof(int))return 0;if(!v->count)return v->first<=v->extent;if(v->first>=v->extent)return 0;size_t step=magnitude(v->stride),moves=v->count-1;return v->stride<0?moves<=v->first/step:moves<=(v->extent-1-v->first)/step;}
enum cd_status cd_view_init(struct cd_view*v,const int*p,size_t extent,size_t first,size_t count,ptrdiff_t stride){if(!v)return CD_INVALID;struct cd_view candidate={p,extent,first,count,stride};if(!view_valid(&candidate))return CD_INVALID;*v=candidate;return CD_OK;}
enum cd_status cd_view_get(const struct cd_view*v,size_t position,int*out){if(!view_valid(v)||!out||position>=v->count)return CD_INVALID;size_t delta=position*magnitude(v->stride);size_t at=v->stride<0?v->first-delta:v->first+delta;*out=v->base[at];return CD_OK;}
enum cd_status cd_view_sub(const struct cd_view*v,size_t start,size_t count,struct cd_view*out){if(!view_valid(v)||!out||start>v->count||count>v->count-start)return CD_INVALID;struct cd_view candidate=*v;candidate.count=count;if(count){size_t delta=start*magnitude(v->stride);candidate.first=v->stride<0?v->first-delta:v->first+delta;}/* Empty view forms no endpoint pointer, even for negative stride. */*out=candidate;return CD_OK;}
static int ring_valid(const struct cd_ring*r){return r&&(!r->capacity||r->data)&&r->count<=r->capacity&&(r->capacity?r->head<r->capacity:r->head==0)&&r->reserved<=r->capacity-r->count;}
static void spans(const struct cd_ring*r,size_t at,size_t n,struct cd_spans*out){size_t first=n;if(n&&first>r->capacity-at)first=r->capacity-at;*out=(struct cd_spans){first?r->data+at:0,first,n>first?r->data:0,n-first};}
enum cd_status cd_ring_init(struct cd_ring*r,int*p,size_t cap){if(!r||(!p&&cap)||cap>SIZE_MAX/sizeof*p)return CD_INVALID;*r=(struct cd_ring){p,cap,0,0,0,0};return CD_OK;}
enum cd_status cd_ring_read(const struct cd_ring*r,struct cd_spans*out){if(!ring_valid(r)||!out)return CD_INVALID;if(r->reserving)return CD_BUSY;spans(r,r->head,r->count,out);return CD_OK;}
enum cd_status cd_ring_reserve(struct cd_ring*r,size_t n,struct cd_spans*out){if(!ring_valid(r)||!out)return CD_INVALID;if(r->reserving)return CD_BUSY;if(n>r->capacity-r->count)return CD_FULL;size_t tail=r->capacity?(r->head>=r->capacity-r->count?r->head-(r->capacity-r->count):r->head+r->count):0;spans(r,tail,n,out);r->reserving=1;r->reserved=n;return CD_OK;}
enum cd_status cd_ring_commit(struct cd_ring*r,size_t n){if(!ring_valid(r)||!r->reserving)return CD_INVALID;if(n>r->reserved&&CD_MUTANT!=2)return CD_INVALID;r->count+=n;r->reserved=0;r->reserving=0;return CD_OK;}
enum cd_status cd_ring_push(struct cd_ring*r,const int*values,size_t n,unsigned partial,size_t*written){if(!ring_valid(r)||!written||(!values&&n)||partial>1)return CD_INVALID;if(r->reserving)return CD_BUSY;size_t amount=n;if(amount>r->capacity-r->count){if(!partial)return CD_FULL;amount=r->capacity-r->count;}struct cd_spans s;enum cd_status status=cd_ring_reserve(r,amount,&s);if(status!=CD_OK)return status;for(size_t i=0;i<s.first_count;++i)s.first[i]=values[i];for(size_t i=0;i<s.second_count;++i)s.second[i]=values[s.first_count+i];cd_ring_commit(r,amount);*written=amount;return CD_OK;}
enum cd_status cd_ring_pop(struct cd_ring*r,int*out,size_t n){if(!ring_valid(r)||(!out&&n))return CD_INVALID;if(r->reserving)return CD_BUSY;if(n>r->count)return CD_EMPTY;for(size_t i=0;i<n;++i){out[i]=r->data[r->head];if(++r->head==r->capacity)r->head=0;}r->count-=n;return CD_OK;}
static int vector_valid(const struct cd_vector*v){return v&&v->live&&v->allocator.take&&v->allocator.release&&v->length<=v->capacity&&(!v->capacity||v->data);}
enum cd_status cd_vector_init(struct cd_vector*v,struct cd_allocator allocator){if(!v||!allocator.take||!allocator.release)return CD_INVALID;*v=(struct cd_vector){0,0,0,allocator,0,1};return CD_OK;}
enum cd_status cd_vector_reserve(struct cd_vector*v,size_t cap){if(!vector_valid(v)||cap>SIZE_MAX/sizeof(int))return CD_INVALID;if(cap<=v->capacity)return CD_OK;if(v->copies>SIZE_MAX-v->length)return CD_FULL;size_t visible=v->length;if(CD_MUTANT==3)++v->length;int*p=v->allocator.take(v->allocator.context,cap);v->length=visible;if(!p)return CD_NOMEM;for(size_t i=0;i<v->length;++i)p[i]=v->data[i];int*old=v->data;v->data=p;v->capacity=cap;v->copies+=v->length;if(old)v->allocator.release(v->allocator.context,old);return CD_OK;}
enum cd_status cd_vector_insert(struct cd_vector*v,size_t at,int value){if(!vector_valid(v)||at>v->length)return CD_INVALID;if(v->length==v->capacity){size_t cap=v->capacity?v->capacity:1;if(v->capacity){if(cap>SIZE_MAX/2)return CD_FULL;cap*=2;}enum cd_status s=cd_vector_reserve(v,cap);if(s!=CD_OK)return s;}for(size_t i=v->length;i>at;--i)v->data[i]=v->data[i-1];v->data[at]=value;++v->length;return CD_OK;}
enum cd_status cd_vector_erase(struct cd_vector*v,size_t at,int*out){if(!vector_valid(v)||!out||at>=v->length)return CD_INVALID;int value=v->data[at];for(size_t i=at+1;i<v->length;++i)if(CD_MUTANT!=8)v->data[i-1]=v->data[i];--v->length;*out=value;return CD_OK;}
enum cd_status cd_vector_shrink(struct cd_vector*v){if(!vector_valid(v))return CD_INVALID;if(v->length==v->capacity)return CD_OK;if(v->copies>SIZE_MAX-v->length)return CD_FULL;int*p=0;if(v->length){p=v->allocator.take(v->allocator.context,v->length);if(!p)return CD_NOMEM;for(size_t i=0;i<v->length;++i)p[i]=v->data[i];}int*old=v->data;v->data=p;v->capacity=v->length;v->copies+=v->length;if(old)v->allocator.release(v->allocator.context,old);return CD_OK;}
enum cd_status cd_vector_destroy(struct cd_vector*v){if(!vector_valid(v))return CD_INVALID;int*old=v->data;v->data=0;v->length=v->capacity=0;v->live=0;if(old)v->allocator.release(v->allocator.context,old);return CD_OK;}
enum cd_status cd_clone_batch(struct cd_payload*out,const struct cd_payload*input,size_t n,struct cd_payload_ops ops){if((!out&&n)||(!input&&n)||n>8||!ops.clone||!ops.destroy)return CD_INVALID;struct cd_payload temp[8];size_t made=0;for(;made<n;++made)if(ops.clone(ops.context,&input[made],&temp[made])){while(made)ops.destroy(ops.context,&temp[--made]);return CD_FAILED;}for(size_t i=0;i<n;++i)out[i]=temp[i];return CD_OK;}
enum cd_status cd_payload_init(struct cd_payload_vector*v,struct cd_payload_allocator a,struct cd_payload_ops ops){if(!v||!a.take||!a.release||!ops.clone||!ops.destroy)return CD_INVALID;*v=(struct cd_payload_vector){0,0,a,ops};return CD_OK;}
enum cd_status cd_payload_append(struct cd_payload_vector*v,const struct cd_payload*input,size_t n){if(!v||(!input&&n)||!v->allocator.take||!v->allocator.release||!v->ops.clone||!v->ops.destroy||v->count>8||n>8-v->count)return CD_INVALID;if(!n)return CD_OK;struct cd_payload*replacement=v->allocator.take(v->allocator.context,v->count+n);if(!replacement)return CD_NOMEM;for(size_t i=0;i<v->count;++i)replacement[i]=v->data[i];size_t made=0;for(;made<n;++made)if(v->ops.clone(v->ops.context,&input[made],&replacement[v->count+made])){while(made)v->ops.destroy(v->ops.context,&replacement[v->count+--made]);v->allocator.release(v->allocator.context,replacement);return CD_FAILED;}struct cd_payload*old=v->data;v->data=replacement;v->count+=n;if(old)v->allocator.release(v->allocator.context,old);return CD_OK;}
enum cd_status cd_payload_destroy(struct cd_payload_vector*v){if(!v||!v->allocator.release||!v->ops.destroy)return CD_INVALID;while(v->count)v->ops.destroy(v->ops.context,&v->data[--v->count]);if(v->data)v->allocator.release(v->allocator.context,v->data);v->data=0;v->allocator.take=0;v->allocator.release=0;return CD_OK;}
